#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    parent.resize(n + 1);
    sizes.assign(n + 1, 1);
    for (int v = 0; v <= n; v++) parent[v] = v;
    sort(edges.begin(), edges.end(), [](const vector<long long>& x, const vector<long long>& y) { return x[2] < y[2]; });
    long long total = 0, taken = 0;
    for (const vector<long long>& e : edges) {
        if (unite((int)e[0], (int)e[1])) {
            total += e[2];
            taken++;
        }
    }
    cout << (taken == n - 1 ? total : -1) << "\n";

    return 0;
}

